import sys
import sqlite3
import xml.etree.ElementTree as ET
from io import BytesIO

def parse_xml_report(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    title = root.attrib.get('title', 'Untitled Report')
    query = root.find('query').text
    columns = root.find('columns')
    column_labels = []
    for col in columns.findall('column'):
        key = col.attrib['key']
        label = col.attrib['label']
        column_labels.append((key, label))
    return title, query, column_labels

def execute_query(db_path, query):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute(query)
    rows = cursor.fetchall()
    conn.close()
    return rows

def generate_html(title, rows, column_labels):
    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>{title}</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <table>
        <thead>
            <tr>
"""
    for key, label in column_labels:
        html += f"                <th>{label}</th>\n"
    html += """            </tr>
        </thead>
        <tbody>
            <tr>
"""
    for row in rows:
        html += "                <td>"
        for i, (key, _) in enumerate(column_labels):
            if i > 0:
                html += "                </td>\n                <td>"
            html += str(row[i])
        html += "                </td>\n"
    html += """            </tr>
        </tbody>
    </table>
</body>
</html>
"""
    return html.encode('utf-8')

def main():
    if len(sys.argv) != 4:
        print("Usage: python xml_report.py <report.xml> <database.db> <output.html>")
        sys.exit(1)

    xml_path = sys.argv[1]
    db_path = sys.argv[2]
    output_path = sys.argv[3]

    try:
        title, query, column_labels = parse_xml_report(xml_path)
        rows = execute_query(db_path, query)
        html_content = generate_html(title, rows, column_labels)
        with open(output_path, 'wb') as f:
            f.write(html_content)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
